<template><section class="referral"><button class="back" @click="$emit('close')">‹ Back to Tools</button><h1>Recommend a friend for £250</h1><p>Enter your friend’s details to invite them to complete onboarding.</p><form v-if="!success" @submit.prevent="send"><label>First name<input v-model="first" required maxlength="100" autocomplete="given-name" /></label><label>Last name<input v-model="last" required maxlength="100" autocomplete="family-name" /></label><label>Email<input v-model="email" required type="email" autocomplete="email" /></label><label>Phone number<input v-model="phone" required type="tel" autocomplete="tel" placeholder="Include country code, e.g. +44" /></label><p v-if="error" role="alert">{{ error }}</p><button class="send" :disabled="saving">{{ saving?'Sending…':'Send' }}</button></form><p v-else role="status">{{ success }}</p></section></template>
<script setup>
import {ref} from 'vue';import {frappeRequest} from 'frappe-ui';defineEmits(['close']);const first=ref(''),last=ref(''),email=ref(''),phone=ref(''),saving=ref(false),error=ref(''),success=ref('');async function send(){if(saving.value)return;saving.value=true;error.value='';try{const r=await frappeRequest({url:'/api/method/onemotion.api.profile_referral.send',params:{first_name:first.value,last_name:last.value,email:email.value,phone:phone.value}});success.value=typeof r==='string'?r:typeof r?.message==='string'?r.message:r?.message?.message||'Referral received. The onboarding invitation has been queued for email delivery.'}catch(e){error.value=e?.messages?.[0]||'Could not send this referral. Please try again.'}finally{saving.value=false}}
</script>
<style scoped>.referral{padding:1rem 1rem 6rem;color:#17202b}h1{font-size:1.3rem;font-weight:600}p{margin:1rem 0;font-size:.9rem}form{display:grid;gap:16px}label{display:grid;gap:6px;font-size:.9rem}input{width:100%;min-height:48px;border:1px solid #cbd5e1;border-radius:8px;padding:10px}.back{color:#a61d1d;min-height:44px}.send{background:#075da8;color:white;border-radius:8px;min-height:48px}.send:disabled{opacity:.5}</style>
